# ==============================================================================
# 2. محركات المراجعة المهنية (Calculation & Logic Engines)
# ==============================================================================
class TrialBalanceEngine:
    @staticmethod
    def verify(accounts: List[Dict[str, Any]]) -> Dict[str, Any]:
        tot_deb = sum(float(a.get('debit', 0.0)) for a in accounts)
        tot_crd = sum(float(a.get('credit', 0.0)) for a in accounts)
        diff = abs(tot_deb - tot_crd)
        return {
            "total_debit": round(tot_deb, 2),
            "total_credit": round(tot_crd, 2),
            "difference": round(diff, 2),
            "is_balanced": diff < 0.05
        }

class MaterialityEngine:
    @staticmethod
    def calculate(b_type: str, b_amt: float, om_pct=5.0, pm_pct=75.0, ctt_pct=5.0) -> Dict[str, Any]:
        om = round(abs(b_amt) * (om_pct / 100.0), 2)
        pm = round(om * (pm_pct / 100.0), 2)
        ctt = round(om * (ctt_pct / 100.0), 2)
        return {
            "benchmark_type": b_type,
            "benchmark_amount": b_amt,
            "overall_percentage": om_pct,
            "overall_materiality": om,
            "performance_percentage": pm_pct,
            "performance_materiality": pm,
            "trivial_percentage": ctt_pct,
            "trivial_threshold": ctt
        }

class SamplingEngine:
    @staticmethod
    def calculate_mus(pop_val: float, tol_mis: float, conf=0.95) -> Dict[str, Any]:
        factor = 3.0 if conf >= 0.95 else 2.31
        interval = max(1.0, round(tol_mis / factor, 2))
        size = int(math.ceil(pop_val / interval))
        size = max(5, min(size, 250))
        return {
            "method": "Monetary Unit Sampling (MUS - ISA 530)",
            "population_value": pop_val,
            "tolerable_misstatement": tol_mis,
            "sampling_interval": interval,
            "recommended_sample_size": size
        }

# ==============================================================================
# 3. خادم الويب السحابي المدمج (Cloud HTTP Server)
# ==============================================================================

def process_gl_stream_payload(file_bytes, filename="ledger.csv"):
    text = file_bytes.decode('utf-8', errors='replace')
    stream = io.StringIO(text)
    
    first_lines = []
    for _ in range(35):
        l = stream.readline()
        if not l: break
        first_lines.append(l)
    
    header_idx = -1
    col_map = {'code': 0, 'name': 1, 'debit': 2, 'credit': 3, 'balance': -1, 'ref': -1}
    
    for i, line in enumerate(first_lines):
        r = [c.strip().lower() for c in line.split(',')]
        temp_map = {'code': -1, 'name': -1, 'debit': -1, 'credit': -1, 'balance': -1, 'ref': -1}
        for j, val in enumerate(r):
            if any(k in val for k in ['code', 'كود', 'رقم الحساب', 'رمز', 'acct']): temp_map['code'] = j
            if any(k in val for k in ['name', 'اسم الحساب', 'البيان', 'وصف', 'title', 'label', 'description']): temp_map['name'] = j
            if any(k in val for k in ['debit', 'مدين', 'dr']) and not any(k in val for k in ['initial', 'افتتاحي', 'opening']): temp_map['debit'] = j
            if any(k in val for k in ['credit', 'دائن', 'cr']) and not any(k in val for k in ['initial', 'افتتاحي', 'opening']): temp_map['credit'] = j
            if any(k in val for k in ['balance', 'الرصيد', 'صافي', 'ending']): temp_map['balance'] = j
            if any(k in val for k in ['ref', 'entry', 'قيد', 'مرجع']): temp_map['ref'] = j
            
        if (temp_map['code'] != -1 or temp_map['name'] != -1) and (temp_map['debit'] != -1 or temp_map['balance'] != -1 or temp_map['credit'] != -1):
            header_idx = i
            col_map = temp_map
            break
            
    stream.seek(0)
    for _ in range(header_idx + 1 if header_idx != -1 else 1):
        stream.readline()
        
    reader = csv.reader(stream)
    aggregated = {}
    suspicious_entries = []
    total_raw_debit = 0.0
    total_raw_credit = 0.0
    line_count = 0
    
    def parse_num(val_str):
        if not val_str: return 0.0
        s = val_str.strip().replace(',', '').replace('(', '').replace(')', '')
        try: return abs(float(s))
        except: return 0.0

    for row in reader:
        line_count += 1
        if not row: continue
        
        code_raw = row[col_map['code']].strip() if col_map['code'] < len(row) else ''
        name_raw = row[col_map['name']].strip() if col_map['name'] < len(row) else f"حساب {code_raw}"
        
        combined = (code_raw + ' ' + name_raw).lower()
        if any(k in combined for k in ['total', 'المجموع', 'الإجمالي', 'الرصيد الافتتاحي', 'opening balance']):
            continue
            
        if not code_raw and not name_raw: continue
        
        deb = parse_num(row[col_map['debit']]) if col_map['debit'] < len(row) else 0.0
        crd = parse_num(row[col_map['credit']]) if col_map['credit'] < len(row) else 0.0
        
        if col_map['balance'] != -1 and col_map['balance'] < len(row) and deb == 0 and crd == 0:
            bal = parse_num(row[col_map['balance']])
            if bal > 0: deb = bal
            else: crd = abs(bal)
            
        if not code_raw and name_raw: code_raw = f"ACC-{len(aggregated)+1}"
        if not name_raw and code_raw: name_raw = f"حساب {code_raw}"
        
        total_raw_debit += deb
        total_raw_credit += crd
        
        if deb >= 100000 and deb % 10000 == 0 and len(suspicious_entries) < 50:
            ref_str = row[col_map['ref']] if col_map['ref'] != -1 and col_map['ref'] < len(row) else f"JV-{line_count}"
            suspicious_entries.append({
                'ref': ref_str,
                'account': f"[{code_raw}] {name_raw}",
                'desc': name_raw,
                'amount': deb,
                'indicator': 'مبلغ دائري كبير (Round Sum Entry)',
                'response': 'فحص المستندات المؤيدة وأمر الصرف'
            })
            
        if code_raw not in aggregated:
            cat = "CurrentAssets"
            if code_raw.startswith('1'): cat = "CurrentAssets"
            elif code_raw.startswith('2'): cat = "CurrentLiabilities"
            elif code_raw.startswith('3'): cat = "Equity"
            elif code_raw.startswith('4'): cat = "Revenue"
            elif code_raw.startswith('5'): cat = "CostOfGoodsSold"
            else: cat = "OperatingExpenses"
            
            aggregated[code_raw] = {
                'code': code_raw,
                'name': name_raw,
                'debit': 0.0,
                'credit': 0.0,
                'cat': cat,
                'line': name_raw,
                'movements': 0,
                'file': filename
            }
        aggregated[code_raw]['debit'] += deb
        aggregated[code_raw]['credit'] += crd
        aggregated[code_raw]['movements'] += 1

    final_accounts = []
    net_debit = 0.0
    net_credit = 0.0
    
    for code, item in aggregated.items():
        net = item['debit'] - item['credit']
        f_deb = net if net > 0 else 0.0
        f_crd = abs(net) if net < 0 else 0.0
        
        final_accounts.append({
            'code': item['code'],
            'name': item['name'],
            'debit': f_deb,
            'credit': f_crd,
            'cat': item['cat'],
            'line': item['line'],
            'movements': item['movements'],
            'file': filename
        })
        net_debit += f_deb
        net_credit += f_crd
        
    return {
        'status': 'success',
        'accounts': final_accounts,
        'total_debit': net_debit,
        'total_credit': net_credit,
        'raw_debit': total_raw_debit,
        'raw_credit': total_raw_credit,
        'total_movements': line_count,
        'suspicious_entries': suspicious_entries,
        'is_balanced': abs(net_debit - net_credit) < 0.05
    }

class MyAuditHTTPHandler(BaseHTTPRequestHandler):
    
    def do_POST(self):
        parsed = urllib.parse.urlparse(self.path)
        path = parsed.path

        if path == '/api/upload/gl':
            content_len = int(self.headers.get('Content-Length', 0))
            if content_len > 0:
                body_bytes = self.rfile.read(content_len)
                # Parse multipart or raw
                content_type = self.headers.get('Content-Type', '')
                file_bytes = body_bytes
                filename = "general_ledger.csv"
                if 'multipart/form-data' in content_type:
                    boundary = content_type.split("boundary=")[-1].encode('ascii')
                    parts = body_bytes.split(boundary)
                    for p in parts:
                        if b'filename="' in p:
                            h_end = p.find(b'\r\n\r\n')
                            if h_end != -1:
                                file_bytes = p[h_end+4:].rstrip(b'\r\n--')
                                break
                                
                result = process_gl_stream_payload(file_bytes, filename)
                self.send_response(200)
                self.send_header('Content-Type', 'application/json; charset=utf-8')
                self.end_headers()
                self.wfile.write(json.dumps(result).encode('utf-8'))
                return
            else:
                self.send_response(400)
                self.end_headers()
                self.wfile.write(b'{"error": "Empty body"}')
                return

    def do_GET(self):
        parsed = urllib.parse.urlparse(self.path)
        path = parsed.path

        if path in ['/', '/index.html']:
            self.send_response(200)
            self.send_header('Content-Type', 'text/html; charset=utf-8')
            self.end_headers()
            self.wfile.write(DASHBOARD_HTML.encode('utf-8'))
        elif path == '/health':
            self.send_response(200)
            self.send_header('Content-Type', 'application/json; charset=utf-8')
            self.end_headers()
            self.wfile.write(json.dumps({"status": "ok", "platform": "My Audit Platform"}).encode('utf-8'))
        elif path == '/api/dashboard/summary':
            self.send_response(200)
            self.send_header('Content-Type', 'application/json; charset=utf-8')
            self.end_headers()
            summary = {
                "status": "Ready",
                "standards": ["ISA", "SOCPA", "ISQM"]
            }
            self.wfile.write(json.dumps(summary).encode('utf-8'))
        else:
            self.send_response(404)
            self.end_headers()

def run_server(port=8000):
    init_database()
    server_address = ('', port)
    httpd = HTTPServer(server_address, MyAuditHTTPHandler)
    print(f"خادم منظومة ماي أودت يعمل الآن على: http://localhost:{port}")
    print("جاهز لاستقبال ميزان المراجعة وتدقيق الحسابات.")
    try:
        httpd.serve_forever()
    except KeyboardInterrupt:
        print("\nتم إيقاف الخادم.")

if __name__ == '__main__':
    port = 8000
    if '--port' in sys.argv:
        try:
            idx = sys.argv.index('--port')
            port = int(sys.argv[idx + 1])
        except Exception:
            pass
    run_server(port)
